"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[6473],{16(e){e.exports=JSON.parse('{"tag":{"label":"Exhaustive Search","permalink":"/concepts/tags/exhaustive-search","allTagsPath":"/concepts/tags","count":1,"items":[{"id":"algorithm-design-paradigms/brute-force","title":"Brute Force and Exhaustive Search","description":"Brute force is the most direct way to design an algorithm: solve the problem by doing exactly what its statement says, with no attempt to exploit its structure. To find an element, look at every position. To find the best combination, generate every combination and keep the best one. To check whether a text contains a word, try the word at every position of the text.","permalink":"/concepts/algorithm-design-paradigms/brute-force"}],"unlisted":false}}')}}]);